{
  "IP": "neorv32_hwspinlock",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "Lock state",
      "Unit": "neorv32_hwspinlock",
      "Information": "The 32-bit lock ownership and availability state held by the spinlock array; spinlock operation depends on it to record which locks are held and to report their status.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "The selected lock_q bit is changed from bus_req_i.rw on line 45, so an unauthorized bus request can modify lock state. A lock can be left asserted by the assignment on line 45, preventing clients from acquiring it and blocking synchronized operation.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could issue a bus request that sets a lock and keep it asserted, corrupting ownership and preventing legitimate clients from acquiring that lock.",
      "Enters Through": [
        "bus_req_i.rw"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        45
      ],
      "Held Lines": [
        45
      ],
      "Exit Lines": [
        68,
        70
      ]
    },
    {
      "Concept ID": "C2",
      "Concept Name": "Lock target selection",
      "Unit": "neorv32_hwspinlock",
      "Information": "The decoded selection of which of the 32 lock entries a per-lock access addresses; it determines which lock state is changed and which selected status bit contributes to the response.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "bus_req_i.addr determines sel on line 51, and sel determines which lock_q entry may change on line 44, so changing the address can redirect a lock operation. The selection gates lock updates on line 44 and masks the per-lock response on line 68, so an attacker can prevent or misroute the intended lock access.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could present an address selecting another lock or no valid lock, redirecting acquisition or release and preventing the intended lock transaction.",
      "Enters Through": [
        "bus_req_i.addr"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        51
      ],
      "Held Lines": [
        51
      ],
      "Exit Lines": [
        68
      ]
    }
  ],
  "Not Kept": [
    {
      "Candidate Name": "Returned lock status",
      "Candidate Unit": "neorv32_hwspinlock",
      "Merged Into": "C1",
      "Why Not Kept": ""
    },
    {
