    },
    {
      "Candidate Name": "Clock and reset controls",
      "Candidate Unit": "neorv32_hwspinlock",
      "Merged Into": "",
      "Why Not Kept": "Clock and reset inputs are excluded conceptual assets, and lines 41-43 and 60-62 only use them to time or reset the lock and response state."
    }
  ],
